const { text, assignee, projectGid, completed, dueOnBefore, dueOnAfter, isBlocked, sortBy, sortAscending } = $.input;

const params = {
  opt_fields: 'gid,name,assignee,assignee.name,due_on,completed,completed_at,notes,tags,tags.name,permalink_url,memberships.section.name'
};

if (text) params.text = text;
if (assignee) params['assignee.any'] = assignee;
if (projectGid) params['projects.any'] = projectGid;
if (completed === true) params.completed = 'true';
if (completed === false) params.completed = 'false';
if (dueOnBefore) params['due_on.before'] = dueOnBefore;
if (dueOnAfter) params['due_on.after'] = dueOnAfter;
if (isBlocked === true) params.is_blocked = 'true';
if (isBlocked === false) params.is_blocked = 'false';

params.sort_by = sortBy || 'modified_at';
params.sort_ascending = String(sortAscending === true);

return { params };

const resp = $.steps.searchTasks.response || {};
const tasks = (resp.data || []).map(t => ({
  gid: t.gid,
  name: t.name,
  assignee: t.assignee ? (t.assignee.name || t.assignee.gid) : 'unassigned',
  dueOn: t.due_on || null,
  completed: !!t.completed,
  completedAt: t.completed_at || null,
  section: t.memberships && t.memberships[0] && t.memberships[0].section ? t.memberships[0].section.name : null,
  tags: (t.tags || []).map(tag => tag.name || tag.gid),
  permalink: t.permalink_url || '',
  notes: t.notes ? t.notes.substring(0, 200) : ''
}));

const open = tasks.filter(t => !t.completed).length;
const done = tasks.filter(t => t.completed).length;
const filters = [];
if ($.input.text) filters.push('text: "' + $.input.text + '"');
if ($.input.assignee) filters.push('assignee: ' + $.input.assignee);
if ($.input.projectGid) filters.push('project: ' + $.input.projectGid);
if ($.input.completed !== undefined) filters.push($.input.completed ? 'completed' : 'incomplete');

return {
  tasks,
  totalCount: tasks.length,
  openCount: open,
  completedCount: done,
  filters: filters.join(', ') || 'none',
  hasMore: !!resp.next_page,
  summary: `Found ${tasks.length} task${tasks.length === 1 ? '' : 's'} (${open} open, ${done} completed)${filters.length ? ' matching: ' + filters.join(', ') : ''}`
};
